51:  const select = document.querySelector<HTMLSelectElement>('#camera-select')!;
52:
53:  const request = (deviceId?: string): void => {
54:    button.disabled = true;
55:    select.disabled = true;
56:    status.textContent = 'カメラの映像を待っています…';
57:    onRequest(deviceId)
58:      // 覚えていたカメラが無くなっていた場合は、おまかせで選び直す。
59:      .catch((error: unknown) => (deviceId ? onRequest() : Promise.reject(error)))
60:      .then(
61:        (info) => {
