83:  // 一度選んでもらったカメラを覚えておき、次回からはそれを使う。
84:  button.addEventListener('click', () => request(localStorage.getItem(CAMERA_KEY) ?? undefined));
85:  select.addEventListener('change', () => {
86:    localStorage.setItem(CAMERA_KEY, select.value);
87:    request(select.value);
88:  });
