47:export function setupCameraButton(onRequest: (deviceId?: string) => Promise<CameraInfo | null>): void {
48:  const button = document.querySelector<HTMLButtonElement>('#camera')!;
49:  const status = document.querySelector<HTMLSpanElement>('#camera-status')!;
50:  const preview = document.querySelector<HTMLDivElement>('#camera-preview')!;
51:  const select = document.querySelector<HTMLSelectElement>('#camera-select')!;
52:
53:  const request = (deviceId?: string): void => {
54:    button.disabled = true;
55:    select.disabled = true;
56:    status.textContent = 'カメラの映像を待っています…';
57:    onRequest(deviceId)
58:      // 覚えていたカメラが無くなっていた場合は、おまかせで選び直す。
59:      .catch((error: unknown) => (deviceId ? onRequest() : Promise.reject(error)))
60:      .then(
61:        (info) => {
62:          if (!info) {
63:            status.textContent = 'このブラウザではカメラを使えません。写真は仮想物体だけになります。';
64:            return;
65:          }
66:          const { video, cameras } = info;
67:          status.textContent = `カメラを使えます (${video.videoWidth}×${video.videoHeight})。`;
68:          select.replaceChildren(...cameras.map((camera) => new Option(camera.label, camera.deviceId)));
69:          select.value = info.deviceId;
70:          preview.querySelector('video')?.remove();
71:          preview.append(video);
72:          preview.hidden = false;
73:        },
74:        (error: unknown) => {
75:          console.error(error);
76:          button.disabled = false;
77:          status.textContent = `カメラを使えませんでした: ${error instanceof Error ? error.message : String(error)}`;
78:        },
79:      )
80:      .finally(() => (select.disabled = false));
81:  };
82:  // Quest のブラウザは、既定ではアバターを映す仮想カメラを選ぶ。名前からは見分けられないので、
83:  // 一度選んでもらったカメラを覚えておき、次回からはそれを使う。
84:  button.addEventListener('click', () => request(localStorage.getItem(CAMERA_KEY) ?? undefined));
85:  select.addEventListener('change', () => {
86:    localStorage.setItem(CAMERA_KEY, select.value);
87:    request(select.value);
88:  });
89:}
