        console.warn('[placement] 永続アンカーを削除できませんでした', error);
      });
    }
    this.placed.length = 0;
    this.unrestored = [];
    this.save();
  }

  private save(): void {
    store([...this.unrestored, ...this.placed.flatMap((p) => (p.uuid ? [{ uuid: p.uuid, kind: p.kind }] : []))]);
